) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


CREATE TABLE IF NOT EXISTS `faquestion` (
  `faquestionid` int(11) NOT NULL AUTO_INCREMENT,
